import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr01905Controller {
  @Get('/annual-leaves')
  async listAnnualLeaves(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자', '임직원');
    const q = checks.queryOf(req.query);
    const leaveYearText = String(q['leaveYear'] ?? '').trim();
    if (leaveYearText === '' || !Number.isInteger(Number(leaveYearText))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 연도를 숫자로 입력하세요.');
    }
    const monthText = String(q['month'] ?? '').trim();
    if (monthText !== '') {
      const m = Number(monthText);
      if (!Number.isInteger(m) || m < 1 || m > 12) {
        throw new ApiError(400, 'VALIDATION_FAILED', '조회 월은 1에서 12 사이의 숫자여야 합니다.');
      }
    }
    const deptText = String(q['departmentId'] ?? '').trim();
    if (deptText !== '' && !Number.isInteger(Number(deptText))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 부서가 올바르지 않습니다.');
    }
    const pageText = String(q['page'] ?? '').trim();
    const page = pageText === '' ? 0 : Number(pageText);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    const sizeText = String(q['size'] ?? '').trim();
    let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const params = {
        leaveYear: leaveYearText,
        departmentId: deptText === '' ? null : deptText,
        size: String(size),
        offset: String(page * size),
      };
      const where = `
        FROM annual_leave a
        JOIN employee e ON e.employee_id = a.employee_id
        WHERE a.leave_year = CAST(:leaveYear AS integer)
          AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))`;
      const countRows = await db.query(
        `SELECT COUNT(*) AS "total" ${where}`,
        { leaveYear: params.leaveYear, departmentId: params.departmentId },
      );
      const total = Number(countRows[0]?.['total'] ?? 0);
      const items = await db.query(
        `SELECT a.annual_leave_id AS "annualLeaveId",
                a.employee_id AS "employeeId",
                a.granted_days AS "grantedDays",
                COALESCE(a.used_days, 0) AS "usedDays",
                COALESCE(a.granted_days, 0) + COALESCE(a.adjusted_days, 0) - COALESCE(a.used_days, 0) AS "remainingDays",
                CAST(NULL AS numeric) AS "monthlyUsedDays"
         ${where}
         ORDER BY a.annual_leave_id
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      return { items, page, size, total };
    });
  }
}

