import { useState } from 'react';
import { call, useData, Band, Badge, DataTable, Pager, Filters, Field, NumberInput, Select, LookupSelect, RefName, Num, Tiles, ErrorText } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const MONTHS: [string, string][] = Array.from({ length: 12 }, (_, i) => [String(i + 1), `${i + 1}월`]);

export default function FnSfr01905Page({ role, notify }: PageProps) {
  const [leaveYear, setLeaveYear] = useState<number | string>(new Date().getFullYear());
  const [month, setMonth] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({ leaveYear: new Date().getFullYear() });
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/annual-leaves', role, undefined, { ...applied, page, size: 20 }),
    [applied, page],
  );

  const search = () => {
    if (leaveYear === '' || typeof leaveYear !== 'number') {
      setFormError('대상 연도를 숫자로 입력하세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ leaveYear, month, departmentId });
  };

  const reset = () => {
    const year = new Date().getFullYear();
    setLeaveYear(year);
    setMonth('');
    setDepartmentId('');
    setFormError('');
    setPage(0);
    setApplied({ leaveYear: year });
  };

  const rows = data?.items ?? [];
  const sum = (key: string) => rows.reduce((acc, r) => acc + Number(r[key] ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>연차 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data?.total ?? 0} />],
            ['생성 일수 (현재 쪽)', <Num value={sum('grantedDays')} />],
            ['사용 일수 (현재 쪽)', <Num value={sum('usedDays')} />],
            ['잔여 연차 (현재 쪽)', <Num value={sum('remainingDays')} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>연차 총괄</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="대상 연도" required>
            <NumberInput value={leaveYear} onChange={setLeaveYear} />
          </Field>
          <Field label="조회 월">
            <Select value={month} onChange={setMonth} options={MONTHS} placeholder="전체" />
          </Field>
          <Field label="조회 부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} placeholder="전체" />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'annualLeaveId', label: '연차 ID' },
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'grantedDays', label: '생성 일수', render: (r) => <Num value={r['grantedDays']} /> },
            { key: 'usedDays', label: '사용 일수', render: (r) => <Num value={r['usedDays']} /> },
            { key: 'remainingDays', label: '잔여 연차', render: (r) => <Num value={r['remainingDays']} /> },
            { key: 'monthlyUsedDays', label: '월별 사용 일수', render: (r) => (r['monthlyUsedDays'] == null ? '-' : <Num value={r['monthlyUsedDays']} />) },
          ]}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '조회된 연차가 없습니다.'}
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
    </div>
  );
}
